import subprocess, sys, os, re, tempfile
EXE="/workspace/executable"
def box(w,h,tag="",extra_lines=None):
    """w = number of columns spanned inclusive (>=2), h = rows inclusive (>=2)"""
    inner=w-2
    lines=["+"+"-"*inner+"+"]
    for r in range(h-2):
        content=tag if r==0 else ""
        lines.append("|"+content.ljust(inner)+"|")
    lines.append("+"+"-"*inner+"+")
    return "\n".join(lines)+"\n"
def run(text,*args):
    d=tempfile.mkdtemp(dir="/tmp/markup-re")
    fi=os.path.join(d,"i.txt"); fo=os.path.join(d,"o.svg")
    open(fi,"w").write(text)
    p=subprocess.run([EXE,fi,fo,"--svg"]+list(args),capture_output=True,text=True)
    s=open(fo).read() if os.path.exists(fo) else ""
    return s,p.stdout,p.stderr,p.returncode
def paths(svg):
    return re.findall(r"<path ([^>]*?)d='([^']*)'",svg)
def main_paths(svg):
    """return list of (stroke, d) excluding shadow"""
    out=[]
    for attrs,d in paths(svg):
        sh = "filter=" in attrs
        st = re.search(r"stroke='([^']*)'",attrs)
        fl = re.search(r"fill(?::\s*|=')([^';]*)",attrs)
        out.append(("SHADOW" if sh else (st.group(1) if st else "?"), d))
    return out
def texts(svg):
    return re.findall(r"<text[^>]*>(.*?)</text>",svg)
def show(text,*args,label=""):
    svg,so,se,rc=run(text,*args)
    print("---",label,args)
    for k,d in main_paths(svg): print("   ",k,"|",d)
    for t in re.findall(r"(<text[^>]*>.*?</text>)",svg): print("   TXT",t)
